//! Spell rule catalogue loader and validator.
//!
//! The asset is generated by the extraction pipeline from MAIN.EXE
//! descriptor bytes and asserted instruction words. This module admits exactly
//! the reviewed 33-entry shape: every definition is accounted for, every
//! supported entry has ordered steps, every non-supported entry carries a named
//! blocker, and the spell-presentation dependency is typed rather than inferred.
//!
//! Rule readiness is deliberately independent of presentation readiness: the
//! `presentation` record must stay `unavailable` until the spell-presentation
//! export supplies the identity-to-frames binding. Nothing here derives a frame, palette or sound.

const std = @import("std");

pub const schema = "suikoden-battle-spell-rules/1";
pub const pack = "battle-spell-rules";
pub const max_steps = 4;

pub const Counts = struct { supported: usize, partial: usize, blocked: usize };

/// Additive step family set over the D contract's version-1 envelope. The
/// envelope itself stays D v1 (`plan.zig`); this number only versions the step
/// vocabulary the C bridge must agree before it is used in combat.
pub const family_version: u8 = 2;

pub const max_targets = 12;

pub const Op = enum { damage, heal, revive, clear_status, sleep, scale_bonus, protection, instant_ko };
pub const TargetSet = enum { selected, all_allies, all_enemies, allies, enemies };
pub const AmountKind = enum { flat, to_max, max_fraction, fraction };

pub const Amount = struct {
    kind: []const u8,
    value: ?u16 = null,
    numerator: ?u16 = null,
    denominator: ?u16 = null,
};

pub const Step = struct {
    airborne_immune: bool = false,
    order: u8,
    op: []const u8,
    target: []const u8,
    power: u16 = 0,
    channel: ?u8 = null,
    channel_name: ?[]const u8 = null,
    resisted: bool = true,
    amount: ?Amount = null,
    clear_status: bool = false,
    failure_percent: ?u8 = null,
    field: ?[]const u8 = null,
    percent: ?u16 = null,
    status_class: ?u8 = null,
    duration: ?u8 = null,
    immune_flag: ?u16 = null,

    pub fn opOf(self: Step) !Op {
        return std.meta.stringToEnum(Op, self.op) orelse error.UnsupportedStep;
    }

    pub fn targetOf(self: Step) !TargetSet {
        return std.meta.stringToEnum(TargetSet, self.target) orelse error.UnsupportedStep;
    }

    pub fn amountOf(self: Step) !AmountKind {
        const amount = self.amount orelse return error.UnsupportedStep;
        return std.meta.stringToEnum(AmountKind, amount.kind) orelse error.UnsupportedStep;
    }
};

pub const Spell = struct {
    native_id: u8,
    id: []const u8,
    name: []const u8,
    target_class: u8,
    target_class_name: []const u8,
    target_side: []const u8,
    selection: []const u8,
    field_use: bool,
    descriptor: []const u8 = "",
    initializer: []const u8 = "",
    family: []const u8,
    status: []const u8,
    family_source: []const u8,
    steps: []Step,
    notes: []const []const u8 = &.{},
    blocker: ?[]const u8 = null,

    pub fn side(self: Spell) !Side {
        return std.meta.stringToEnum(Side, self.target_side) orelse error.InvalidRules;
    }

    pub fn single(self: Spell) bool {
        return std.mem.eql(u8, self.selection, "single");
    }
};

pub const Side = enum { ally, enemy };

pub const Presentation = struct {
    status: []const u8,
    package: []const u8,
    code: []const u8,
    owner: []const u8,
    required_interface: []const u8,
    detail: []const u8,
};

pub const TierCharge = struct {
    thresholds: [4][9]u8,
    counter_record: []const u8,
    refill_routine: []const u8,
    spend_routine: []const u8,
    menu_reader: []const u8,
    spend_rule: []const u8,
    refill_rule: []const u8,
    menu_rule: []const u8,
};

pub const Rules = struct {
    schema: []const u8,
    pack: []const u8,
    spells: []Spell,
    presentation: Presentation,
    tier_charge: TierCharge,
    damage: DamageModel,
    hp_gate: HpGateModel,
    status: StatusModel,

    pub const DamageModel = struct {
        consumer: []const u8,
        formula: []const u8,
        affinity_source: []const u8,
        caster_magic_source: []const u8,
        unresisted_channel: u8,
        unresisted_rule: []const u8,
    };
    pub const HpGateModel = struct {
        routine: []const u8,
        rule: []const u8,
    };
    pub const StatusModel = struct {
        cure: []const u8,
        setter: []const u8,
        cure_classes: []const u8,
        excluded_classes: []const u8,
        ordering: []const u8,
    };

    pub fn spell(self: *const Rules, native_id: u8) ?*const Spell {
        for (self.spells) |*entry| if (entry.native_id == native_id) return entry;
        return null;
    }

    pub fn spellIndex(self: *const Rules, native_id: u8) ?usize {
        for (self.spells, 0..) |entry, i| if (entry.native_id == native_id) return i;
        return null;
    }

    pub fn counts(self: *const Rules) Counts {
        var out = Counts{ .supported = 0, .partial = 0, .blocked = 0 };
        for (self.spells) |entry| {
            if (std.mem.eql(u8, entry.status, "supported")) out.supported += 1 else if (std.mem.eql(u8, entry.status, "partial")) out.partial += 1 else if (std.mem.eql(u8, entry.status, "blocked")) out.blocked += 1;
        }
        return out;
    }

    pub fn validate(self: Rules) !void {
        if (!std.mem.eql(u8, self.schema, schema) or !std.mem.eql(u8, self.pack, pack)) return error.InvalidRules;
        if (self.spells.len != 33) return error.InvalidRules;
        if (self.presentation.status.len == 0 or self.presentation.detail.len < 64) return error.InvalidPresentationDependency;
        if (!std.mem.eql(u8, self.presentation.status, "unavailable")) return error.InvalidPresentationDependency;
        if (!std.mem.eql(u8, self.presentation.package, "spell_presentation")) return error.InvalidPresentationDependency;
        if (!std.mem.eql(u8, self.presentation.code, "presentation_correction_unavailable")) return error.InvalidPresentationDependency;
        if (!std.mem.eql(u8, self.presentation.owner, "magic_actions")) return error.InvalidPresentationDependency;
        if (!std.mem.eql(u8, self.presentation.required_interface, "spell_identity_to_presentation_frames_and_audio")) return error.InvalidPresentationDependency;

        var derived: usize = 0;
        var supported: usize = 0;
        var partial: usize = 0;
        var blocked: usize = 0;
        for (self.spells, 0..) |entry, index| {
            if (entry.native_id != index + 1 or entry.id.len == 0 or entry.name.len == 0) return error.InvalidRules;
            if (entry.target_class > 3 or entry.family.len == 0) return error.InvalidRules;
            if (entry.target_class_name.len == 0 or entry.selection.len == 0) return error.InvalidRules;
            for (self.spells[0..index]) |previous| {
                if (std.mem.eql(u8, previous.id, entry.id) or previous.native_id == entry.native_id) return error.InvalidRules;
            }
            const spell_side = entry.side() catch return error.InvalidRules;
            if (entry.target_class == 0 or entry.target_class == 2) {
                if (spell_side != .ally) return error.InvalidRules;
            } else if (spell_side != .enemy) return error.InvalidRules;
            if (std.mem.eql(u8, entry.family_source, "spell_rules.static")) derived += 1;
            if (std.mem.eql(u8, entry.status, "supported")) {
                supported += 1;
                if (entry.steps.len == 0 or entry.blocker != null) return error.InvalidRules;
            } else if (std.mem.eql(u8, entry.status, "partial")) {
                partial += 1;
                if (entry.steps.len == 0 or entry.blocker == null) return error.InvalidRules;
            } else if (std.mem.eql(u8, entry.status, "blocked")) {
                blocked += 1;
                if (entry.steps.len != 0 or entry.blocker == null) return error.InvalidRules;
            } else return error.InvalidRules;
            if (entry.steps.len > max_steps) return error.InvalidRules;
            for (entry.steps, 0..) |step, step_index| {
                if (step.order != @as(u8, @intCast(step_index))) return error.InvalidRules;
                const op = try step.opOf();
                _ = try step.targetOf();
                if (step.airborne_immune and op != .damage) return error.InvalidRules;
                switch (op) {
                    .damage => {
                        const channel = step.channel orelse return error.InvalidRules;
                        if (channel > 5 and channel != self.damage.unresisted_channel) return error.InvalidRules;
                        if (step.power == 0) return error.InvalidRules;
                        if (channel == self.damage.unresisted_channel and step.resisted) return error.InvalidRules;
                    },
                    .heal => {
                        _ = try step.amountOf();
                        const amount = step.amount.?;
                        switch (try step.amountOf()) {
                            .flat => if (amount.value == null or amount.value.? == 0) return error.InvalidRules,
                            .max_fraction => {
                                if (amount.numerator == null or amount.denominator == null or amount.denominator.? == 0) return error.InvalidRules;
                                if (amount.numerator.? == 0 or amount.numerator.? > amount.denominator.?) return error.InvalidRules;
                            },
                            .fraction => if (amount.numerator == null or amount.numerator.? > 100) return error.InvalidRules,
                            .to_max => {},
                        }
                    },
                    .revive, .clear_status => {},
                    .sleep => {
                        if (step.power == 0) return error.InvalidRules;
                        if (step.failure_percent) |percent| if (percent > 100) return error.InvalidRules;
                    },
                    .scale_bonus => {
                        if (step.field == null or step.percent == null or step.percent.? == 0 or step.percent.? > 200) return error.InvalidRules;
                        if (!std.mem.eql(u8, step.field.?, "skill") and !std.mem.eql(u8, step.field.?, "defense")) return error.InvalidRules;
                    },
                    .protection => if (step.power == 0 or step.power > 10) return error.InvalidRules,
                    .instant_ko => {
                        if (step.immune_flag == null or step.immune_flag.? == 0) return error.InvalidRules;
                    },
                }
            }
        }
        if (derived != 7) return error.InvalidRules;
        if (supported + partial + blocked != 33) return error.InvalidRules;
        // The tier/charge model must be the source shape: four rows of nine.
        for (self.tier_charge.thresholds) |row| {
            var previous: u8 = 0;
            for (row) |threshold| {
                if (threshold == 0 or threshold <= previous) return error.InvalidRules;
                previous = threshold;
            }
        }
        if (self.tier_charge.spend_routine.len == 0 or self.tier_charge.counter_record.len == 0) return error.InvalidRules;
    }
};

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Rules) {
    if (bytes.len > 512 * 1024) return error.AssetTooLarge;
    const parsed = try std.json.parseFromSlice(Rules, allocator, bytes, .{ .allocate = .alloc_always, .ignore_unknown_fields = true });
    errdefer parsed.deinit();
    try parsed.value.validate();
    return parsed;
}
